public class Solution {
    static String t1, t2; static int[][] memo;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        t1 = sc.nextLine().trim(); t2 = sc.nextLine().trim();
        memo = new int[t1.length()][t2.length()];
        for (int[] row : memo) Arrays.fill(row, -1);
        System.out.println(lcs(0, 0));
    }
    static int lcs(int i, int j) {
        if (i == t1.length() || j == t2.length()) return 0;
        if (memo[i][j] != -1) return memo[i][j];
        if (t1.charAt(i) == t2.charAt(j)) return memo[i][j] = 1 + lcs(i+1, j+1);
        return memo[i][j] = Math.max(lcs(i+1, j), lcs(i, j+1));
    }
}

